app_css:
.tool-app-cakeflow { color: #3f1d2e; max-width: 1200px; margin-inline: auto; font-size: 14px; }
.tool-app-cakeflow .cf-toolbar { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; background: #fff; border: 1px solid #f9d5e3; border-radius: 14px; padding: 10px 16px; margin-bottom: 12px; }
.tool-app-cakeflow .cf-title h2 { margin: 0; font-size: 20px; color: #9d174d; }
.tool-app-cakeflow .cf-title p { margin: 2px 0 0; color: #8a4b63; font-size: 13px; }
.tool-app-cakeflow .cf-toolbar-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.tool-app-cakeflow .cf-toolbar-actions input[type="search"] { border: 1px solid #f9a8c7; border-radius: 10px; padding: 8px 12px; font-size: 13px; min-width: 160px; }
.tool-app-cakeflow .cf-view-toggle { display: flex; border: 1px solid #f9a8c7; border-radius: 10px; overflow: hidden; }
.tool-app-cakeflow .cf-viewbtn { background: #fff; border: none; padding: 8px 12px; font-size: 13px; font-weight: 600; color: #9d174d; cursor: pointer; }
.tool-app-cakeflow .cf-viewbtn-active { background: #fce7f1; }
.tool-app-cakeflow .cf-btn { background: #db2777; color: #fff; border: none; border-radius: 10px; padding: 9px 16px; font-size: 13px; font-weight: 700; cursor: pointer; }
.tool-app-cakeflow .cf-btn:hover { background: #be185d; }
.tool-app-cakeflow .cf-btn-ghost { background: #fce7f1; color: #9d174d; }
.tool-app-cakeflow .cf-btn-ghost:hover { background: #fbcfe8; }
.tool-app-cakeflow .cf-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 12px; }
.tool-app-cakeflow .cf-stats > div { background: #fff; border: 1px solid #f9d5e3; border-radius: 12px; padding: 10px 14px; display: flex; justify-content: space-between; align-items: center; }
.tool-app-cakeflow .cf-stats span { font-size: 12px; color: #8a4b63; font-weight: 600; }
.tool-app-cakeflow .cf-stats strong { font-size: 18px; color: #9d174d; }
.tool-app-cakeflow .cf-board { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 10px; align-items: start; }
.tool-app-cakeflow .cf-col { background: #fff5f8; border: 1px solid #f9d5e3; border-radius: 12px; padding: 8px; min-height: 140px; }
.tool-app-cakeflow .cf-col h3 { margin: 4px 4px 8px; font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; color: #9d174d; display: flex; justify-content: space-between; }
.tool-app-cakeflow .cf-col h3 .cf-count { background: #fbcfe8; border-radius: 999px; padding: 0 8px; font-size: 11px; }
.tool-app-cakeflow .cf-card { background: #fff; border: 1px solid #fbcfe8; border-radius: 10px; padding: 10px; margin-bottom: 8px; box-shadow: 0 1px 2px rgba(157, 23, 77, 0.06); }
.tool-app-cakeflow .cf-card-top { display: flex; justify-content: space-between; align-items: baseline; gap: 6px; }
.tool-app-cakeflow .cf-card-top strong { font-size: 14px; }
.tool-app-cakeflow .cf-due { font-size: 11px; font-weight: 700; border-radius: 999px; padding: 2px 8px; background: #fce7f1; color: #9d174d; white-space: nowrap; }
.tool-app-cakeflow .cf-due-soon { background: #fef3c7; color: #92400e; }
.tool-app-cakeflow .cf-due-over { background: #fee2e2; color: #991b1b; }
.tool-app-cakeflow .cf-card-meta { font-size: 12px; color: #8a4b63; margin: 6px 0; line-height: 1.5; }
.tool-app-cakeflow .cf-card-notes { font-size: 12px; font-style: italic; color: #6b4a5a; margin: 4px 0; }
.tool-app-cakeflow .cf-card-money { display: flex; justify-content: space-between; font-size: 12px; margin: 6px 0; }
.tool-app-cakeflow .cf-card-money strong { color: #15803d; }
.tool-app-cakeflow .cf-card-actions { display: flex; gap: 4px; margin-top: 6px; }
.tool-app-cakeflow .cf-card-actions button { flex: 1; border: 1px solid #f9a8c7; background: #fff; border-radius: 8px; padding: 5px 0; font-size: 12px; font-weight: 700; color: #9d174d; cursor: pointer; }
.tool-app-cakeflow .cf-card-actions button:hover { background: #fce7f1; }
.tool-app-cakeflow .cf-card-actions .cf-del { flex: 0 0 auto; padding: 5px 10px; color: #b91c1c; border-color: #fecaca; }
.tool-app-cakeflow .cf-empty { text-align: center; color: #b76e88; font-size: 12px; padding: 14px 4px; }
.tool-app-cakeflow .cf-pickup-table { width: 100%; border-collapse: collapse; background: #fff; border-radius: 12px; overflow: hidden; }
.tool-app-cakeflow .cf-pickup-table th { text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; color: #9d174d; padding: 10px; background: #fce7f1; }
.tool-app-cakeflow .cf-pickup-table td { padding: 10px; border-top: 1px solid #fce7f1; font-size: 13px; vertical-align: top; }
.tool-app-cakeflow .cf-pickup-table tr.cf-row-over td { background: #fef2f2; }
.tool-app-cakeflow .cf-modal-backdrop { position: fixed; inset: 0; background: rgba(63, 29, 46, 0.5); display: flex; align-items: center; justify-content: center; z-index: 50; padding: 16px; }
.tool-app-cakeflow .cf-modal { background: #fff; border-radius: 16px; padding: 20px; width: 100%; max-width: 560px; max-height: 90vh; overflow: auto; box-shadow: 0 20px 50px rgba(0,0,0,0.2); }
.tool-app-cakeflow .cf-modal h3 { margin: 0 0 12px; color: #9d174d; }
.tool-app-cakeflow .cf-formgrid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.tool-app-cakeflow .cf-formgrid .cf-full { grid-column: 1 / -1; }
.tool-app-cakeflow .cf-formgrid label { display: flex; flex-direction: column; gap: 4px; font-size: 12px; font-weight: 600; color: #6b4a5a; }
.tool-app-cakeflow .cf-formgrid input, .tool-app-cakeflow .cf-formgrid select, .tool-app-cakeflow .cf-formgrid textarea { border: 1px solid #f9a8c7; border-radius: 8px; padding: 8px 10px; font-size: 14px; font-weight: 400; color: #3f1d2e; width: 100%; box-sizing: border-box; }
.tool-app-cakeflow .cf-error { color: #b91c1c; font-size: 13px; font-weight: 600; }
.tool-app-cakeflow .cf-modal-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 14px; }
@media (max-width: 640px) { .tool-app-cakeflow .cf-formgrid { grid-template-columns: 1fr; } .tool-app-cakeflow .cf-stats { grid-template-columns: 1fr; } .tool-app-cakeflow .cf-pickup-table th:nth-child(5), .tool-app-cakeflow .cf-pickup-table td:nth-child(5), .tool-app-cakeflow .cf-pickup-table th:nth-child(4), .tool-app-cakeflow .cf-pickup-table td:nth-child(4) { display: none; } }

app_js:
(function () {
  'use strict';
  var STAGES = ["Inquiry", "Quoted", "Booked", "In production", "Ready", "Done"];
  var LS_KEY = 'toolapp-cakeflow-orders';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { n = parseFloat(n); return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  function todayStr() { var d = new Date(); return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
  function pad(n) { return (n < 10 ? '0' : '') + n; }
  function parseDate(s) { var p = String(s || '').split('-'); return p.length === 3 ? new Date(p[0], p[1] - 1, p[2]) : null; }
  function fmtDate(s) { var d = parseDate(s); if (!d) return ''; return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }); }
  function daysUntil(s) {
    var d = parseDate(s); if (!d) return null;
    var t = parseDate(todayStr());
    return Math.round((d - t) / 864e5);
  }
  function uid() { return 'cf' + Date.now().toString(36) + Math.floor(Math.random() * 1e6).toString(36); }

  function load() { try { return JSON.parse(localStorage.getItem(LS_KEY)) || []; } catch (e) { return []; } }
  function save(orders) { try { localStorage.setItem(LS_KEY, JSON.stringify(orders)); } catch (e) {} }

  var editingId = null;

  function balance(o) { return (parseFloat(o.price) || 0) - (parseFloat(o.deposit) || 0); }

  function dueBadge(o) {
    var du = daysUntil(o.date);
    if (du == null) return '';
    var cls = '', label = fmtDate(o.date);
    if (du < 0 && o.stage !== 'Done') { cls = ' cf-due-over'; label = 'Overdue: ' + fmtDate(o.date); }
    else if (du === 0) { cls = ' cf-due-soon'; label = 'Today'; }
    else if (du === 1) { cls = ' cf-due-soon'; label = 'Tomorrow'; }
    else if (du <= 3 && o.stage !== 'Done') { cls = ' cf-due-soon'; }
    return '<span class="cf-due' + cls + '">' + esc(label) + '</span>';
  }

  function cardHTML(o) {
    var si = STAGES.indexOf(o.stage);
    var prev = si > 0 ? '<button type="button" data-act="prev" title="Move back">&#8592;</button>' : '';
    var next = si < STAGES.length - 1 ? '<button type="button" data-act="next" title="Move forward">&#8594;</button>' : '';
    var cake = [o.size, o.flavor, o.servings ? o.servings + ' servings' : ''].filter(Boolean).join(' &middot; ');
    return '<div class="cf-card-top"><strong>' + esc(o.customer) + '</strong>' + dueBadge(o) + '</div>' +
      '<div class="cf-card-meta">' + esc(fmtDate(o.date)) + (o.time ? ' &middot; ' + esc(o.time) : '') +
      (o.phone ? '<br>' + esc(o.phone) : '') +
      (cake ? '<br>' + cake : '') + '</div>' +
      (o.notes ? '<div class="cf-card-notes">&ldquo;' + esc(o.notes) + '&rdquo;</div>' : '') +
      '<div class="cf-card-money"><span>Total ' + money(o.price) + ' &middot; Deposit ' + money(o.deposit) + '</span><strong>' +
      (balance(o) > 0 ? 'Due ' + money(balance(o)) : 'Paid') + '</strong></div>' +
      '<div class="cf-card-actions" data-id="' + esc(o.id) + '">' + prev + next +
      '<button type="button" data-act="edit">Edit</button>' +
      '<button type="button" data-act="del" class="cf-del" aria-label="Delete order">&times;</button></div>';
  }

  function render() {
    var orders = load();
    var q = ($('cf-search').value || '').toLowerCase();
    var board = $('cf-board');
    board.innerHTML = '';
    STAGES.forEach(function (stage) {
      var col = document.createElement('div');
      col.className = 'cf-col';
      var list = orders.filter(function (o) { return o.stage === stage && (!q || (o.customer || '').toLowerCase().indexOf(q) !== -1); });
      var inner = '<h3>' + esc(stage) + '<span class="cf-count">' + list.length + '</span></h3>';
      if (!list.length) inner += '<div class="cf-empty">No orders</div>';
      list.sort(function (a, b) { return String(a.date).localeCompare(String(b.date)); });
      for (var i = 0; i < list.length; i++) inner += '<div class="cf-card">' + cardHTML(list[i]) + '</div>';
      col.innerHTML = inner;
      board.appendChild(col);
    });
    renderStats(orders);
    renderPickup(orders, q);
  }

  function renderStats(orders) {
    var t = todayStr();
    var active = 0, week = 0, due = 0;
    for (var i = 0; i < orders.length; i++) {
      var o = orders[i];
      if (o.stage === 'Done') continue;
      active++;
      var du = daysUntil(o.date);
      if (du != null && du >= 0 && du <= 7) week++;
      var b = balance(o);
      if (b > 0) due += b;
    }
    $('cf-stat-active').textContent = active;
    $('cf-stat-week').textContent = week;
    $('cf-stat-due').textContent = money(due);
  }

  function renderPickup(orders, q) {
    var list = orders.filter(function (o) {
      return o.stage !== 'Done' && (!q || (o.customer || '').toLowerCase().indexOf(q) !== -1);
    });
    list.sort(function (a, b) { return String(a.date).localeCompare(String(b.date)); });
    var tb = $('cf-pickup-body');
    var html = '';
    for (var i = 0; i < list.length; i++) {
      var o = list[i];
      var du = daysUntil(o.date);
      var rowCls = (du != null && du < 0) ? ' class="cf-row-over"' : '';
      var cake = [o.size, o.flavor, o.servings ? o.servings + ' servings' : ''].filter(Boolean).join(', ');
      html += '<tr' + rowCls + '><td><strong>' + esc(fmtDate(o.date)) + '</strong>' + (o.time ? '<br>' + esc(o.time) : '') + '</td>' +
        '<td><strong>' + esc(o.customer) + '</strong>' + (o.phone ? '<br>' + esc(o.phone) : '') + '</td>' +
        '<td>' + esc(cake) + (o.notes ? '<br><em>' + esc(o.notes) + '</em>' : '') + '</td>' +
        '<td>' + money(o.price) + '</td><td>' + money(o.deposit) + '</td>' +
        '<td><strong>' + (balance(o) > 0 ? money(balance(o)) : 'Paid') + '</strong></td>' +
        '<td>' + esc(o.stage) + '</td></tr>';
    }
    tb.innerHTML = html || '<tr><td colspan="7" style="text-align:center;color:#b76e88;">No upcoming pickups</td></tr>';
  }

  function openModal(order) {
    editingId = order ? order.id : null;
    $('cf-modal-title').textContent = order ? 'Edit order' : 'New order';
    $('cf-f-customer').value = order ? order.customer : '';
    $('cf-f-phone').value = order ? (order.phone || '') : '';
    $('cf-f-date').value = order ? order.date : todayStr();
    $('cf-f-time').value = order ? (order.time || '') : '';
    $('cf-f-servings').value = order ? (order.servings || '') : '';
    $('cf-f-size').value = order ? (order.size || '8 inch') : '8 inch';
    $('cf-f-flavor').value = order ? (order.flavor || '') : '';
    $('cf-f-price').value = order ? order.price : '';
    $('cf-f-deposit').value = order ? order.deposit : '';
    $('cf-f-notes').value = order ? (order.notes || '') : '';
    $('cf-form-error').hidden = true;
    $('cf-modal-backdrop').hidden = false;
    $('cf-f-customer').focus();
  }

  function closeModal() { $('cf-modal-backdrop').hidden = true; editingId = null; }

  function saveForm() {
    var customer = $('cf-f-customer').value.trim();
    var date = $('cf-f-date').value;
    var price = parseFloat($('cf-f-price').value);
    var err = $('cf-form-error');
    if (!customer) { err.textContent = 'Customer name is required.'; err.hidden = false; return; }
    if (!date) { err.textContent = 'Pickup date is required.'; err.hidden = false; return; }
    if (!isFinite(price) || price < 0) { err.textContent = 'Enter a valid total price.'; err.hidden = false; return; }
    var orders = load();
    var data = {
      customer: customer,
      phone: $('cf-f-phone').value.trim(),
      date: date,
      time: $('cf-f-time').value,
      servings: $('cf-f-servings').value ? parseInt($('cf-f-servings').value, 10) : null,
      size: $('cf-f-size').value,
      flavor: $('cf-f-flavor').value.trim(),
      price: price,
      deposit: parseFloat($('cf-f-deposit').value) || 0,
      notes: $('cf-f-notes').value.trim()
    };
    if (editingId) {
      for (var i = 0; i < orders.length; i++) {
        if (orders[i].id === editingId) { for (var k in data) orders[i][k] = data[k]; break; }
      }
    } else {
      data.id = uid();
      data.stage = 'Inquiry';
      data.createdAt = new Date().toISOString();
      orders.unshift(data);
    }
    save(orders);
    closeModal();
    render();
  }

  function onCardAction(btn) {
    var act = btn.getAttribute('data-act');
    var id = btn.parentElement.getAttribute('data-id');
    var orders = load();
    var idx = -1;
    for (var i = 0; i < orders.length; i++) { if (orders[i].id === id) { idx = i; break; } }
    if (idx === -1) return;
    if (act === 'next' || act === 'prev') {
      var si = STAGES.indexOf(orders[idx].stage);
      si += (act === 'next' ? 1 : -1);
      if (si >= 0 && si < STAGES.length) orders[idx].stage = STAGES[si];
      save(orders); render();
    } else if (act === 'edit') {
      openModal(orders[idx]);
    } else if (act === 'del') {
      if (confirm('Delete the order for ' + (orders[idx].customer || 'this customer') + '?')) {
        orders.splice(idx, 1);
        save(orders); render();
      }
    }
  }

  function seed() {
    if (load().length) return;
    var d = new Date();
    function plus(n) { var x = new Date(d.getTime() + n * 864e5); return x.getFullYear() + '-' + pad(x.getMonth() + 1) + '-' + pad(x.getDate()); }
    save([
      { id: uid(), customer: 'Sample: Maya R.', phone: '', date: plus(2), time: '4:00 PM', servings: 24, size: '8 inch', flavor: 'Red velvet', price: 95, deposit: 30, notes: 'Blush pink, gold topper', stage: 'Booked', createdAt: new Date().toISOString() },
      { id: uid(), customer: 'Sample: T. Nguyen', phone: '', date: plus(5), time: '11:00 AM', servings: 40, size: 'Tiered', flavor: 'Vanilla bean', price: 220, deposit: 0, notes: '', stage: 'Quoted', createdAt: new Date().toISOString() }
    ]);
  }

  document.getElementById('toolAppRoot').addEventListener('click', function (e) {
    var t = e.target;
    if (t.id === 'cf-add') { openModal(null); return; }
    if (t.id === 'cf-form-cancel') { closeModal(); return; }
    if (t.id === 'cf-form-save') { saveForm(); return; }
    if (t.id === 'cf-modal-backdrop') { closeModal(); return; }
    if (t.id === 'cf-view-board') { $('cf-view-board').classList.add('cf-viewbtn-active'); $('cf-view-pickup').classList.remove('cf-viewbtn-active'); $('cf-board').hidden = false; $('cf-pickup').hidden = true; return; }
    if (t.id === 'cf-view-pickup') { $('cf-view-pickup').classList.add('cf-viewbtn-active'); $('cf-view-board').classList.remove('cf-viewbtn-active'); $('cf-board').hidden = true; $('cf-pickup').hidden = false; return; }
    if (t.getAttribute && t.getAttribute('data-act')) { onCardAction(t); return; }
  });
  document.getElementById('toolAppRoot').addEventListener('input', function (e) {
    if (e.target && e.target.id === 'cf-search') render();
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && !$('cf-modal-backdrop').hidden) closeModal();
  });

  seed();
  render();
})();
